import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  cartItems: [],
  totalQuantity: 0,
  totalPrice: 0,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addProduct(state, action) {
      const existingProduct = state.cartItems.find(
        (item) => item.product.id === action.payload.product.id
      );
      if (existingProduct) {
        existingProduct.quantity += action.payload.quantity;
      } else {
        state.cartItems.push({
          product: action.payload.product,
          quantity: action.payload.quantity,
        });
      }
      state.totalQuantity += action.payload.quantity;
      state.totalPrice += action.payload.product.price * action.payload.quantity;
    },
    removeProduct(state, action) {
      state.cartItems = state.cartItems.filter(
        (item) => item.product.id!== action.payload.productId
      );
      state.totalQuantity -= action.payload.quantity;
      state.totalPrice -= action.payload.product.price * action.payload.quantity;
    },
    updateQuantity(state, action) {
      const product = state.cartItems.find(
        (item) => item.product.id === action.payload.productId
      );
      if (product) {
        product.quantity = action.payload.newQuantity;
        state.totalQuantity += action.payload.newQuantity - product.quantity;
        state.totalPrice += (action.payload.newQuantity - product.quantity) * product.product.price;
      }
    },
  },
});

export const { addProduct, removeProduct, updateQuantity } = cartSlice.actions;
export default cartSlice.reducer;
