import React, { useState } from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem } from './cartSlice';
import { selectCartItems } from './selectors';

const CartComponent = () => {
  const dispatch = useDispatch();
  const cartItems = useSelector(selectCartItems);
  const [quantity, setQuantity] = useState(1);

  const removeFromCart = (id) => dispatch(removeItem(id));
  const addToCart = (item) => {
    dispatch(addItem(item));
  };

  const handleQuantityChange = (id, newQuantity) => {
    const index = cartItems.findIndex((item) => item.id === id);
    if (index!== -1) {
      cartItems[index].quantity = newQuantity;
      dispatch(addItem(cartItems[index]));
    }
  };

  return (
    <div className="cart-component">
      <h2>Cart</h2>
      {cartItems.length === 0? (
        <p>Cart is empty</p>
      ) : (
        cartItems.map((item) => (
          <div key={item.id} className="cart-item">
            <h3>{item.name}</h3>
            <p>Quantity: {item.quantity}</p>
            <button onClick={() => removeFromCart(item.id)}>Remove</button>
            <button onClick={() => setQuantity(quantity + 1)}>+</button>
            <button onClick={() => setQuantity(quantity - 1)} disabled={quantity === 1}>-</button>
            <button onClick={() => handleQuantityChange(item.id, quantity)}>Save</button>
          </div>
        ))
      )}
      <button onClick={() => addToCart({ id: 1, name: 'New Item' })}>Add new item to cart</button>
    </div>
  );
};

export default CartComponent;
```

